const fs = require("node:fs");
const path = require("node:path");

const root = path.resolve(__dirname, "..");
const sources = [
  "dist/vendor/xlsx.full.min.js",
  "dist/eda-core.js",
  "dist/app.js",
];

const output = [
  "/* Generated by scripts/build-bundle.cjs. Do not edit directly. */",
  ...sources.map((source) => fs.readFileSync(path.join(root, source), "utf8")),
].join("\n;\n");

fs.writeFileSync(path.join(root, "dist/bundle.js"), output, "utf8");
console.log(`Built dist/bundle.js from ${sources.length} sources.`);
